input.command:
cd /tmp/ys && cat > /tmp/ys/m5.yaml <<'EOF'
a: &a {p: A, q: A, r: A}
b: &b {q: B, s: B}
t1: {<<: *a, q: OWN, z: OWN}
t2: {p: OWN, <<: *a, z: OWN}
t3: {<<: *a, <<: *b}
t4: {<<: [*a, *b], q: OWN}
t5: {q: OWN, <<: [*a, *b]}
EOF
for f in "" "--yaml-fix-merge-anchor-to-spec"; do echo "######## flag='$f'"; for k in t1 t2 t3 t4 t5; do echo "-- $k:"; /workspace/executable $f -o=json -I=0 ".$k" /tmp/ys/m5.yaml 2>/dev/null; done; done

cd /tmp/ys && cat > /tmp/ys/m6.yaml <<'EOF'
a: &a {p: A, q: A, r: A}
t6: {r: OWN, <<: *a, z: OWN}
t7: {q: OWN, <<: *a}
t8: {<<: *a, p: OWN}
t9: {zz: 1, q: OWN, <<: *a}
EOF
for f in "" "--yaml-fix-merge-anchor-to-spec"; do echo "######## flag='$f'"; for k in t6 t7 t8 t9; do printf "%s: " $k; /workspace/executable $f -o=json -I=0 ".$k" /tmp/ys/m6.yaml 2>/dev/null; done; done

cd /tmp/ys && cat > /tmp/ys/m7.yaml <<'EOF'
a: &a {p: A, q: A, r: A}
b: &b {q: B, s: B}
u1: {<<: [*a], q: OWN}
u2: {<<: [*a, *b], p: OWN}
u3: {<<: [*b, *a], q: OWN}
u4: {<<: [*a, *b]}
u5: {<<: [*b, *a]}
u6: {<<: *a, <<: *b, q: OWN}
u7: {<<: [*a, *b], s: OWN, p: OWN2}
EOF
for f in "" "--yaml-fix-merge-anchor-to-spec"; do echo "######## flag='$f'"; for k in u1 u2 u3 u4 u5 u6 u7; do printf "%s: " $k; /workspace/executable $f -o=json -I=0 ".$k" /tmp/ys/m7.yaml 2>/dev/null; done; done
